void ACLSelectorRemoveCommandRule(aclSelector *selector, sds new_rule) {
    size_t new_len = sdslen(new_rule);

    /* Split the rules into their individual tokens, drop the ones matching the
     * new rule, and rebuild the string. This avoids operating on a string while
     * it is being shifted in place, which could cause stale data to be scanned
     * and leave duplicate or removed rules behind. */
    int argc = 0;
    sds *argv = sdssplitargs(selector->command_rules, &argc);
    serverAssert(argv != NULL);

    sds rules = sdsempty();
    for (int i = 0; i < argc; i++) {
        sds rule = argv[i];
        size_t rule_len = sdslen(rule);

        /* The first character of the rule is +/-, which we don't need to compare. */
        const char *cmd = rule + 1;
        size_t cmd_len = rule_len - 1;

        /* Exact match or the rule we are comparing is a subcommand denoted by '|' */
        int match = (cmd_len == new_len && !memcmp(cmd, new_rule, new_len)) ||
                    (cmd_len > new_len && cmd[new_len] == '|' &&
                     !memcmp(cmd, new_rule, new_len));

        if (!match) {
            if (sdslen(rules)) rules = sdscat(rules, " ");
            rules = sdscatsds(rules, rule);
        }
    }

    sdsfreesplitres(argv, argc);
    sdsfree(selector->command_rules);
    selector->command_rules = rules;
}

